//! 📥️ Native receiving copies one original wire descriptor under the receiving actor's supplied authority.
use super::{ResultPageDelivery,TypedOperationResultToken,TYPED_OPERATION_RESULT_HEADER_BYTES};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,admit_retained_clone_progress},retirement::controlled::ControlledRetirement};
use std::mem::{ManuallyDrop,size_of};
#[derive(Clone,Copy,PartialEq,Eq)]
enum Stage{Allocate,Copy,SourceClose,Ready,Closed}
/// 🧳️ The original descriptor remains owned until its receiving alias has physically closed.
pub struct ResultPageWireReceiver{source:ManuallyDrop<Option<ResultPageDelivery>>,wire:ManuallyDrop<Option<Vec<u8>>>,retirement:Option<ControlledRetirement<Vec<u8>>>,token:TypedOperationResultToken,length:usize,stage:Stage,closing:bool}
fn fits(d:RetirementDemand,g:RetainedCloneGrant)->bool{g.maximum_items>0&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes&&g.maximum_depth>=d.depth}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl ResultPageWireReceiver{
 fn header_bytes()->usize{size_of::<Stage>()+size_of::<usize>()+size_of::<Option<Vec<u8>>>()+size_of::<Option<ResultPageDelivery>>()}
 /// 🎟️ Captures only a complete original descriptor; refusal leaves the caller's slot untouched.
 pub fn capture_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()*2+size_of::<Option<ResultPageDelivery>>(),depth:1,..Default::default()}}
 pub fn capture(slot:&mut Option<ResultPageDelivery>,grant:RetainedCloneGrant)->Result<Option<(Self,RetainedCloneProgress)>,ValueError>{let d=Self::capture_demand();if !fits(d,grant){return Ok(None)}let source=slot.as_ref().ok_or_else(||invalid("native wire receiving requires its original descriptor"))?;if !source.ready(){return Err(invalid("native wire receiving requires complete original framing"))}let token=source.token().ok_or_else(||invalid("original descriptor token is absent"))?;let length=source.header()?.len().checked_add(source.body()?.len()).ok_or_else(||invalid("native wire receiving length overflows"))?;Ok(Some((Self{source:ManuallyDrop::new(slot.take()),wire:ManuallyDrop::new(Some(Vec::new())),retirement:None,token,length,stage:Stage::Allocate,closing:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))}
 pub fn token(&self)->TypedOperationResultToken{self.token}
 pub fn ready(&self)->bool{self.stage==Stage::Ready&&!self.closing&&self.source.is_none()}
 pub fn terminal_is_empty(&self)->bool{self.source.is_none()&&self.wire.is_none()&&self.retirement.is_none()}
 /// 📏️ The destination allocation is quoted independently from the bounded body-copy currency.
 pub fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.next_close_demand(body)}let parent=Self::header_bytes();let mut d=match self.stage{Stage::Allocate=>RetirementDemand{capacity_bytes:self.length,depth:1,..Default::default()},Stage::Copy=>RetirementDemand{copy_bytes:self.length.saturating_sub(self.wire.as_ref().unwrap().len()).min(4096usize.saturating_sub(parent)),depth:1,..Default::default()},Stage::SourceClose=>self.source.as_ref().unwrap().next_close_demand(body.saturating_sub(parent))?,Stage::Ready|Stage::Closed=>return Ok(Default::default())};d.copy_bytes=d.copy_bytes.checked_add(parent).ok_or_else(||invalid("wire receiving copy quote overflows"))?;Ok(d)}
 /// 🧵️ Each turn forwards the actual allocation, copy or original source-close receipt.
 pub fn advance(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.closing{return self.close_step(grant)}if self.ready()||self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.next_demand(grant.maximum_copy_bytes)?;if !fits(d,grant){return Ok(RetainedCloneStep::Progress(Default::default()))}let parent=Self::header_bytes();let mut p=match self.stage{
 Stage::Allocate=>{let wire=self.wire.as_mut().unwrap();wire.try_reserve_exact(self.length).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"native wire destination allocation failed"))?;self.stage=Stage::Copy;RetainedCloneProgress{copied_items:1,retained_capacity_bytes:wire.capacity(),..Default::default()}},
 Stage::Copy=>{let source=self.source.as_ref().unwrap();let header=source.header()?;let body=source.body()?;let wire=self.wire.as_mut().unwrap();let available=d.copy_bytes-parent;if available==0{return Ok(RetainedCloneStep::Progress(Default::default()))}let begin=wire.len();let end=begin+available;if begin<header.len(){wire.extend_from_slice(&header[begin..end.min(header.len())]);}if end>header.len(){wire.extend_from_slice(&body[begin.saturating_sub(header.len())..end-header.len()]);}if wire.len()==self.length{self.source.as_mut().unwrap().begin_close();self.stage=Stage::SourceClose;}RetainedCloneProgress{copied_items:1,copied_bytes:available,..Default::default()}},
 Stage::SourceClose=>{let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-parent,..grant};let source=self.source.as_mut().unwrap();let p=source.close_step(child)?.progress();if source.terminal_is_empty(){self.source.take();self.stage=Stage::Ready;}else if p==RetainedCloneProgress::default(){return Ok(RetainedCloneStep::Progress(p))}p},Stage::Ready|Stage::Closed=>unreachable!()};p.copied_items=p.copied_items.max(1);p.copied_bytes+=parent;let p=admit_retained_clone_progress(grant,p,"original native wire receiving")?;Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 /// 📤️ Transfers the original destination only after the source alias is completely retired.
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid("wire output cannot precede original descriptor close"))}Ok(RetirementDemand{copy_bytes:size_of::<Vec<u8>>()+size_of::<Option<Vec<u8>>>()+size_of::<Stage>(),depth:1,..Default::default()})}
 pub fn take_wire(&mut self,grant:RetainedCloneGrant)->Result<Option<(Vec<u8>,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !fits(d,grant){return Ok(None)}self.stage=Stage::Closed;Ok(Some((self.wire.take().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))}
 pub fn begin_close(&mut self){self.closing=true;if let Some(source)=self.source.as_mut(){source.begin_close();}}
 pub fn next_close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}let parent=Self::header_bytes();let mut d=if let Some(source)=self.source.as_ref(){source.next_close_demand(body.saturating_sub(parent))?}else if let Some(owner)=self.retirement.as_ref(){owner.next_demand(body.saturating_sub(parent))?}else{RetirementDemand{depth:1,..Default::default()}};d.copy_bytes=d.copy_bytes.checked_add(parent).ok_or_else(||invalid("wire receiving cleanup quote overflows"))?;Ok(d)}
 /// ♻️ Cancellation retires both the original descriptor and any partial receiving allocation.
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid("wire receiving requires explicit cancellation before cleanup"))}if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.next_close_demand(grant.maximum_copy_bytes)?;if !fits(d,grant){return Ok(RetainedCloneStep::Progress(Default::default()))}let parent=Self::header_bytes();let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-parent,..grant};let mut p=if let Some(source)=self.source.as_mut(){let p=source.close_step(child)?.progress();if source.terminal_is_empty(){self.source.take();}else if p==RetainedCloneProgress::default(){return Ok(RetainedCloneStep::Progress(p))}p}else if let Some(owner)=self.retirement.as_mut(){let p=owner.step(child)?.progress();if owner.terminal_is_empty(){self.retirement=None;}else if p==RetainedCloneProgress::default(){return Ok(RetainedCloneStep::Progress(p))}p}else{let wire=self.wire.take().unwrap();self.retirement=Some(ControlledRetirement::new(wire).map_err(|_|invalid("native byte receiving retirement is unsupported"))?);RetainedCloneProgress{copied_items:1,..Default::default()}};p.copied_items=p.copied_items.max(1);p.copied_bytes+=parent;let p=admit_retained_clone_progress(grant,p,"original native wire receiving cleanup")?;Ok(if self.terminal_is_empty(){self.stage=Stage::Closed;RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
}
impl Drop for ResultPageWireReceiver{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native wire receiving reached Drop before original source and partial destination closed");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.source);ManuallyDrop::drop(&mut self.wire);}}}}
